<?php
declare(strict_types=1);
require __DIR__ . '/includes/bootstrap.php';
$user=app_require_permission('wholesale.manage');
$initialAccount=trim((string)($_GET['account']??''));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Wholesale Quote & Order Entry</title><style>:root{--bg:#f2f1ed;--panel:#fff;--ink:#171815;--muted:#6b706a;--line:#deded8;--accent:#d94a2b;--dark:#171b1a;--good:#157347}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}button,input,select,textarea{font:inherit}.top{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 22px;background:#fff;border-bottom:1px solid var(--line)}.actions{display:flex;gap:7px}.btn{min-height:38px;padding:8px 12px;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--ink);font-weight:850;font-size:10px;text-decoration:none;cursor:pointer}.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}.shell{max-width:1300px;margin:auto;padding:28px}.hero{display:flex;justify-content:space-between;gap:18px;align-items:end;margin-bottom:16px}.eyebrow{margin:0;color:var(--accent);font-size:9px;font-weight:950;text-transform:uppercase;letter-spacing:.12em}.hero h1{font-size:38px;letter-spacing:-.05em;margin:6px 0}.hero p{color:var(--muted);font-size:11px;margin:0;max-width:760px}.panel{background:#fff;border:1px solid var(--line);border-radius:16px;padding:16px;margin-bottom:12px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.wide{grid-column:1/-1}.span2{grid-column:span 2}label{display:block;font-size:8px;font-weight:900;color:#5c615c;margin-bottom:4px;text-transform:uppercase}.field{width:100%;min-height:42px;border:1px solid var(--line);border-radius:9px;padding:9px 10px;background:#fff}.lines{display:grid;gap:8px}.line{display:grid;grid-template-columns:minmax(260px,1fr) 120px 120px 120px 44px;gap:8px;align-items:end;padding:10px;border:1px solid var(--line);border-radius:11px}.price,.ext{min-height:42px;display:flex;align-items:center;padding:8px 10px;border-radius:9px;background:#f5f4f0;font-size:11px;font-weight:800}.remove{width:42px;height:42px;border:0;border-radius:9px;background:#f1efeb;font-size:18px}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.metric{padding:12px;border-radius:11px;background:#f5f4f0}.metric small{display:block;color:var(--muted);font-size:8px;font-weight:900;text-transform:uppercase}.metric strong{display:block;margin-top:5px;font-size:18px}.notice{padding:10px;border-radius:10px;background:#eef8f1;color:#145c38;font-size:10px}.muted{color:var(--muted);font-size:9px}@media(max-width:900px){.grid{grid-template-columns:1fr 1fr}.line{grid-template-columns:1fr 100px 100px}.line .price,.line .remove{grid-column:auto}.summary{grid-template-columns:1fr 1fr}}@media(max-width:600px){.grid,.summary,.line{grid-template-columns:1fr}.wide,.span2{grid-column:auto}.hero{display:block}.shell{padding:16px}}</style></head><body><header class="top"><strong>Wholesale Quote & Order Entry</strong><div class="actions"><a class="btn" href="wholesale-accounts.php">Accounts</a><a class="btn" href="wholesale-commerce.php">Commerce Setup</a><a class="btn" href="wholesale-pipeline.php">Pipeline</a></div></header><main class="shell"><div class="hero"><div><p class="eyebrow">Canonical commerce</p><h1>Build from the account price list</h1><p>Every line resolves by wholesale SKU. MOQ, order minimum, unit price, tax and totals are enforced again on the server when the quote or order is saved.</p></div><button class="btn" id="addLine">+ Add line</button></div><section class="panel"><div class="grid"><div class="span2"><label>Wholesale account</label><select class="field" id="account"><option value="">Choose account…</option></select></div><div><label>Document type</label><select class="field" id="mode"><option value="quote">Quote</option><option value="order">Order</option></select></div><div><label>Active price list</label><div class="price" id="priceList">—</div></div></div></section><section class="panel"><div class="lines" id="lines"></div><div class="muted" id="catalogStatus" style="margin-top:9px">Choose an account to load its wholesale catalog.</div></section><section class="panel"><div class="grid"><div><label>Delivery fee</label><input class="field" id="delivery" type="number" min="0" step=".01" value="0"></div><div><label>Tax rate %</label><input class="field" id="taxRate" type="number" min="0" max="30" step=".0001" value="0"></div><div class="quoteOnly"><label>Quote valid until</label><input class="field" id="validUntil" type="date"></div><div class="orderOnly" style="display:none"><label>Requested for</label><input class="field" id="requestedFor" type="date"></div><div class="orderOnly" style="display:none"><label>Fulfillment</label><select class="field" id="fulfillment"><option>Delivery</option><option>Pickup</option></select></div><div class="quoteOnly wide"><label>Customer message</label><textarea class="field" id="message" rows="2"></textarea></div><div class="orderOnly wide" style="display:none"><label>Customer notes</label><textarea class="field" id="orderNotes" rows="2"></textarea></div></div></section><section class="panel"><div class="summary"><div class="metric"><small>Subtotal preview</small><strong id="subtotal">$0.00</strong></div><div class="metric"><small>Delivery</small><strong id="deliveryPreview">$0.00</strong></div><div class="metric"><small>Tax preview</small><strong id="tax">$0.00</strong></div><div class="metric"><small>Total preview</small><strong id="total">$0.00</strong></div></div><p class="muted">These are previews only. The server recalculates the saved document from the canonical SKU price list.</p><button class="btn primary" id="submit" disabled>Create quote</button><div id="result" style="margin-top:10px"></div></section></main><script>window.WOE={csrf:<?=json_encode(app_csrf_token(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,initial:<?=json_encode($initialAccount)?>};</script><script>(()=>{const cfg=window.WOE,$=id=>document.getElementById(id),money=v=>'$'+Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});let catalog=[],accounts=[];async function api(url,opt={}){const r=await fetch(url,{cache:'no-store',headers:{Accept:'application/json',...(opt.body?{'Content-Type':'application/json','X-CSRF-Token':cfg.csrf}:{}),...(opt.headers||{})},...opt}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Request failed');return d}function optionHtml(){return '<option value="">Choose SKU…</option>'+catalog.map(x=>`<option value="${x.id}">${String(x.sku).replace(/[&<>]/g,'')} · ${String(x.name).replace(/[&<>]/g,'')} · ${money(x.unitPrice)} / ${String(x.sellUom).replace(/[&<>]/g,'')} · min ${x.priceMinimumQuantity??x.minimumQuantity}</option>`).join('')}function addLine(skuId='',qty=1){const row=document.createElement('div');row.className='line';row.innerHTML=`<div><label>SKU</label><select class="field sku">${optionHtml()}</select></div><div><label>Quantity</label><input class="field qty" type="number" min="0.0001" step=".0001" value="${qty}"></div><div><label>Unit price</label><div class="price">—</div></div><div><label>Extended</label><div class="ext">$0.00</div></div><button class="remove" type="button">×</button>`;row.querySelector('.sku').value=skuId;row.querySelector('.remove').onclick=()=>{row.remove();preview()};row.querySelector('.sku').onchange=preview;row.querySelector('.qty').oninput=preview;$('lines').appendChild(row);preview()}function linesPayload(){return [...$('lines').querySelectorAll('.line')].map(r=>({skuId:r.querySelector('.sku').value,quantity:Number(r.querySelector('.qty').value||0)})).filter(x=>x.skuId&&x.quantity>0)}function preview(){let subtotal=0;[...$('lines').querySelectorAll('.line')].forEach(r=>{const item=catalog.find(x=>x.id===r.querySelector('.sku').value),q=Number(r.querySelector('.qty').value||0),p=item&&item.unitPrice!=null?Number(item.unitPrice):0,e=q*p;r.querySelector('.price').textContent=item?money(p)+' / '+item.sellUom:'—';r.querySelector('.ext').textContent=money(e);subtotal+=e});const delivery=Math.max(0,Number($('delivery').value||0)),rate=Math.max(0,Number($('taxRate').value||0)),tax=subtotal*rate/100;$('subtotal').textContent=money(subtotal);$('deliveryPreview').textContent=money(delivery);$('tax').textContent=money(tax);$('total').textContent=money(subtotal+delivery+tax);$('submit').disabled=!$('account').value||linesPayload().length===0}async function loadAccounts(){const d=await api('api/wholesale-accounts.php?action=list');accounts=d.accounts||[];$('account').innerHTML='<option value="">Choose account…</option>'+accounts.map(a=>`<option value="${a.public_id}">${String(a.business_name).replace(/[&<>]/g,'')}</option>`).join('');if(cfg.initial&&accounts.some(a=>a.public_id===cfg.initial)){$('account').value=cfg.initial;await loadCatalog()}}async function loadCatalog(){catalog=[];$('lines').innerHTML='';const id=$('account').value;if(!id){$('priceList').textContent='—';$('catalogStatus').textContent='Choose an account to load its wholesale catalog.';preview();return}try{const d=await api('api/wholesale-commerce.php?action=catalog&accountId='+encodeURIComponent(id));catalog=(d.catalog||[]).filter(x=>x.unitPrice!=null);const pl=catalog[0]?.priceList;$('priceList').textContent=pl?pl.name+(pl.minimumOrderAmount>0?' · $'+Number(pl.minimumOrderAmount).toFixed(2)+' minimum':''):'No active priced catalog';$('catalogStatus').textContent=catalog.length?catalog.length+' priced SKU'+(catalog.length===1?'':'s')+' available.':'No priced SKUs are available for this account. Configure products and pricing first.';if(catalog.length)addLine()}catch(e){$('catalogStatus').textContent=e.message}$('submit').disabled=!catalog.length;preview()}function mode(){const quote=$('mode').value==='quote';document.querySelectorAll('.quoteOnly').forEach(e=>e.style.display=quote?'':'none');document.querySelectorAll('.orderOnly').forEach(e=>e.style.display=quote?'none':'');$('submit').textContent=quote?'Create quote':'Create order'}async function submit(){const accountId=$('account').value,items=linesPayload();if(!accountId||!items.length)return;const isQuote=$('mode').value==='quote';const body={action:isQuote?'quote':'order',accountId,items,deliveryFee:Number($('delivery').value||0),taxRatePercent:Number($('taxRate').value||0),csrf_token:cfg.csrf};if(isQuote){body.status='sent';body.validUntil=$('validUntil').value;body.customerMessage=$('message').value}else{body.status='confirmed';body.requestedFor=$('requestedFor').value;body.fulfillmentType=$('fulfillment').value;body.customerNotes=$('orderNotes').value}try{$('submit').disabled=true;const d=await api('api/wholesale-accounts.php',{method:'POST',body:JSON.stringify(body)});$('result').innerHTML=`<div class="notice">${String(d.message).replace(/[&<>]/g,'')} <strong>${String(d.quoteNumber||d.orderNumber||'').replace(/[&<>]/g,'')}</strong></div>`}catch(e){$('result').innerHTML=`<div class="notice" style="background:#fff0ee;color:#8d2b1d">${String(e.message).replace(/[&<>]/g,'')}</div>`}finally{preview()}}$('account').onchange=loadCatalog;$('mode').onchange=mode;$('delivery').oninput=preview;$('taxRate').oninput=preview;$('addLine').onclick=()=>catalog.length&&addLine();$('submit').onclick=submit;const dt=new Date();dt.setDate(dt.getDate()+14);$('validUntil').value=dt.toISOString().slice(0,10);$('requestedFor').value=dt.toISOString().slice(0,10);mode();loadAccounts()})();</script></body></html>
